const { io } = require(path.join(ROOT, "node_modules/socket.io-client"));
const http = require("http");
const net = require("net");

// JSON target for HTTP json-query monitor (exercises axios + jsonata)
http.createServer((req, res) => {
    res.setHeader("Content-Type", "application/json");
    res.end(JSON.stringify({ status: "ok", data: { count: 5 } }));
}).listen(4100);

// minimal fake SMTP server (exercises nodemailer transport + SMTP monitor)
const mails = [];
net.createServer((s) => {
    let inData = false, buf = "";
    s.write("220 fake ESMTP\r\n");
    s.on("data", (d) => {
        buf += d.toString();
        let idx;
        while ((idx = buf.indexOf("\r\n")) >= 0) {
            const line = buf.slice(0, idx); buf = buf.slice(idx + 2);
            if (inData) {
                if (line === ".") { inData = false; s.write("250 queued\r\n"); } else { mails[mails.length - 1] += line + "\n"; }
                continue;
            }
            const cmd = line.slice(0, 4).toUpperCase();
            if (cmd === "EHLO" || cmd === "HELO") s.write("250-fake\r\n250 8BITMIME\r\n");
            else if (cmd === "MAIL" || cmd === "RCPT" || cmd === "RSET" || cmd === "NOOP") s.write("250 ok\r\n");
            else if (cmd === "DATA") { inData = true; mails.push(""); s.write("354 go\r\n"); }
            else if (cmd === "QUIT") { s.write("221 bye\r\n"); s.end(); }
            else s.write("250 ok\r\n");
        }
    });
}).listen(2525);

const socket = io("http://127.0.0.1:3999", { transports: ["websocket"] });
const emit = (ev, ...args) => new Promise((r) => socket.emit(ev, ...args, r));
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const heartbeats = {};
socket.on("heartbeat", (h) => { (heartbeats[h.monitorID] ||= []).push(h); });

let fail = 0;
const check = (name, cond, extra = "") => { console.log((cond ? "PASS " : "FAIL ") + name, extra); if (!cond) fail++; };

(async () => {
    await new Promise((r) => socket.on("connect", r));
    let res = await emit("setup", "admin", "Adm1nPassw0rd!xyz");
    check("setup", res.ok || /already/i.test(res.msg), JSON.stringify(res));
    res = await emit("login", { username: "admin", password: "Adm1nPassw0rd!xyz", token: "" });
    check("login", res.ok, JSON.stringify(res).slice(0, 100));
    res = await emit("login", { username: "admin", password: "wrong", token: "" });
    check("login wrong pw rejected", !res.ok);

    const base = { notificationIDList: {}, interval: 20, retryInterval: 20, maxretries: 0, accepted_statuscodes: ["200-299"], conditions: [], kafkaProducerBrokers: [], kafkaProducerSaslOptions: {}, rabbitmqNodes: [] };
    res = await emit("add", { ...base, type: "json-query", name: "jq", url: "http://127.0.0.1:4100/", method: "GET", jsonPath: "data.count * 2", jsonPathOperator: "==", expectedValue: "10" });
    check("add json-query monitor", res.ok, JSON.stringify(res));
    const jqId = res.monitorID;
    res = await emit("add", { ...base, type: "http", name: "http", url: "http://127.0.0.1:4100/", method: "GET" });
    check("add http monitor", res.ok);
    const httpId = res.monitorID;
    res = await emit("add", { ...base, type: "smtp", name: "smtp", hostname: "127.0.0.1", port: 2525, smtpSecurity: "nostarttls" });
    check("add smtp monitor", res.ok, JSON.stringify(res));
    const smtpId = res.monitorID;

    res = await emit("testNotification", { type: "smtp", name: "mail", smtpHost: "127.0.0.1", smtpPort: 2525, smtpSecure: false, smtpIgnoreSTARTTLS: true, smtpFrom: "kuma@example.com", smtpTo: "ops@example.com", customSubject: "[{{ status }}] {{ name | upcase }}", customBody: "Msg: {{ msg }}" });
    check("smtp notification test (nodemailer+liquid)", res.ok, JSON.stringify(res));
    check("mail received with liquid-rendered subject", mails.length === 1 && /Subject: .*TESTING|Subject: \[/i.test(mails[0]), mails[0] && mails[0].split("\n").find((l) => l.startsWith("Subject")));

    res = await emit("addStatusPage", "Test Page", "test-page");
    check("add status page", res.ok, JSON.stringify(res));

    await sleep(8000);
    const last = (id) => (heartbeats[id] || []).slice(-1)[0];
    check("json-query monitor UP", last(jqId)?.status === 1, last(jqId)?.msg);
    check("http monitor UP", last(httpId)?.status === 1, last(httpId)?.msg);
    check("smtp monitor UP", last(smtpId)?.status === 1, last(smtpId)?.msg);

    // negative json-query
    res = await emit("add", { ...base, type: "json-query", name: "jq-bad", url: "http://127.0.0.1:4100/", method: "GET", jsonPath: "data.count", jsonPathOperator: "==", expectedValue: "999" });
    await sleep(5000);
    check("json-query mismatch is DOWN", last(res.monitorID)?.status === 0, last(res.monitorID)?.msg);

    console.log(fail ? `${fail} FAILED` : "ALL PASSED");
    process.exit(fail ? 1 : 0);
})();

